async function receiveRadioCall(d,from){if(d.action==='request'){if(d.expires&&Date.now()>d.expires)return;if(talkSession||incomingTalk){post({type:'radio-call',action:'reject',id:d.id},from).catch(()=>{});return}incomingTalk={id:d.id,to:from};$('talkInviteText').textContent=displayName()+' quer conversar pelo TALK.';$('talkInvite').showModal();playAlert('call');talkTimer=setTimeout(()=>{if(incomingTalk?.id===d.id)rejectTalk()},30000);return}if(d.action==='end'){if(talkSession?.id===d.id||incomingTalk?.id===d.id)closeTalkSession(false);return}if(!talkSession||talkSession.id!==d.id||talkSession.to!==from)return;if(d.action==='accept'&&talkSession.state==='waiting'){clearTimeout(talkTimer);talkSession.state='accepted';renderTalk();toast('Chamada aceita. Segure TALK para falar.');window.PulsoAndroid?.syncState().catch(()=>{})}if(d.action==='reject'){closeTalkSession(false);toast('O contato recusou a chamada.')}}
async function rejectTalk(){const c=incomingTalk;if(!c)return;closeTalkSession(false);await post({type:'radio-call',action:'reject',id:c.id},c.to).catch(()=>{})}
$('acceptTalk').onclick=async()=>{const c=incomingTalk;if(!c)return;try{await prepareMic();if(incomingTalk!==c)return;await post({type:'radio-call',action:'accept',id:c.id},c.to);if(incomingTalk!==c)return;clearTimeout(talkTimer);incomingTalk=null;talkSession={...c,state:'accepted'};$('talkInvite').close();renderTalk();window.PulsoAndroid?.syncState().catch(()=>{});}catch(e){toast(e.message);rejectTalk()}};$('rejectTalk').onclick=rejectTalk;$('talkInvite').addEventListener('cancel',e=>{e.preventDefault();rejectTalk()});$('endTalk').onclick=()=>closeTalkSession();
function validHold(epoch,to){return held&&holdEpoch===epoch&&radioEnabled&&conn?.code===to&&!videoCall}
async function press(epoch=holdEpoch){if(!held||!conn||!radioEnabled||remoteTalking||videoCall)return;const to=conn.code,nextBurst=crypto.randomUUID(),session=holdMode==='talk'?talkSession?.id:'';if(holdMode==='talk'&&talkSession?.state!=='accepted')return;try{await prepareMic();if(!validHold(epoch,to))return;await waitVoiceDelivery();if(!validHold(epoch,to))return;await post({type:'talk',on:true,burst:nextBurst,session:session||undefined},to);if(!validHold(epoch,to)){post({type:'talk',on:false,burst:nextBurst,session:session||undefined},to).catch(()=>{});return}burstId=nextBurst;burstSession=session;voiceSeq=0;talk=true;samples=[];if(source&&processor)source.connect(processor);stream.getAudioTracks().forEach(t=>t.enabled=true);const activeButton=$(holdMode==='talk'?'talkPtt':'ptt');activeButton.classList.add('active');activeButton.setAttribute('aria-pressed','true');$('radioState').textContent='Você está falando'}catch(e){if(holdEpoch===epoch)release();toast(e.message)}}
function release(){const wasTalking=talk,to=conn?.code,endingBurst=burstId;held=false;holdEpoch++;activePointer=null;holdKind='';clearTimeout(holdTimer);holdTimer=null;talk=false;stream?.getAudioTracks().forEach(t=>t.enabled=false);try{source?.disconnect()}catch{}for(const id of ['ptt','talkPtt']){$(id).classList.remove('active');$(id).classList.remove('pressing');$(id).setAttribute('aria-pressed','false')}$('radioState').textContent=remoteTalking?'Contato falando…':'Canal livre';if(wasTalking){const tail=samples.splice(0);if(tail.length)queueVoice(tail);sending=post({type:'talk',on:false,burst:endingBurst,session:burstSession||undefined},to).catch(()=>{})}else samples=[]}
function schedulePCM(data){const binary=atob(data.audio),v=new DataView(Uint8Array.from(binary,c=>c.charCodeAt(0)).buffer),buffer=context.createBuffer(1,Math.floor(v.byteLength/2),16000),out=buffer.getChannelData(0);for(let i=0;i<out.length;i++)out[i]=v.getInt16(i*2,true)/32768;const node=context.createBufferSource();node.buffer=buffer;node.connect(context.destination);if(nextAudio<context.currentTime+.025)nextAudio=context.currentTime+.6;if(nextAudio-context.currentTime>10)nextAudio=context.currentTime+.6;node.start(nextAudio);nextAudio+=buffer.duration}
function flushVoice(rx,skipGap=false){if(skipGap&&rx.waiting.size&&!rx.waiting.has(rx.next))rx.next=Math.min(...rx.waiting.keys());while(rx.waiting.has(rx.next)){const data=rx.waiting.get(rx.next);rx.waiting.delete(rx.next++);schedulePCM(data)}clearTimeout(rx.timer);if(rx.waiting.size)rx.timer=setTimeout(()=>{if(context?.state==='running')flushVoice(rx,true)},1200)}
function flushPendingPCM(){if(!context||context.state!=='running'||!pendingPCM.length)return;const queued=pendingPCM.splice(0);for(const d of queued)playPCM(d)}
async function playPCM(data){if(!context||context.state!=='running'){pendingPCM.push(data);if(pendingPCM.length>12)pendingPCM.shift();$('hint').textContent='Toque em Ativar áudio para ouvir neste celular.';controls();return}if(typeof data.burst==='string'&&Number.isInteger(data.seq)&&data.seq>=0){let rx=rxBursts.get(data.burst);if(!rx){if(rxBursts.size>=4){const oldest=rxBursts.keys().next().value;clearTimeout(rxBursts.get(oldest).timer);rxBursts.delete(oldest)}rx={next:0,waiting:new Map(),timer:null};rxBursts.set(data.burst,rx)}if(data.seq<rx.next)return;rx.waiting.set(data.seq,data);flushVoice(rx)}else schedulePCM(data)}
function fileMessage(d,mine=false){const e=log('',mine),b=document.createElement('button');b.textContent='↓ '+d.name+' • '+Math.ceil(d.size/1024)+' KB';b.onclick=async()=>{try{const blob=await api('download',{query:{id:d.id},raw:true});const a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=d.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){toast(e.message)}};e.append(b)}
async function receive(packet){let d;try{d=JSON.parse(packet.payload)}catch{return}if(!radioEnabled)return;if(conn&&conn.code!==packet.sender)return;if(!conn){const contact=await api('contact',{query:{code:packet.sender}});link(packet.sender,contact.name)}if(d.type==='radio-call'){await receiveRadioCall(d,packet.sender);return}if((d.type==='talk'||d.type==='pcm')&&d.session&&!(talkSession?.state==='accepted'&&talkSession.id===d.session&&talkSession.to===packet.sender))return;if(d.type==='hello'){conn.name=String(d.name||'Contato').slice(0,40);renderContact();if(!d.reply)post({type:'hello',name:$('name').value||'Contato',reply:true}).catch(()=>{})}if(d.type==='text'){playAlert('message');log(String(d.text||'').slice(0,10000));if(document.hidden&&!pushActive)backgroundAlert('Nova mensagem de '+displayName(),'message')}if(d.type==='file'){playAlert('message');fileMessage(d)}if(d.type==='talk'){if(!d.on&&d.burst&&currentRemoteBurst&&d.burst!==currentRemoteBurst)return;if(d.on)currentRemoteBurst=d.burst||'';if(d.on&&talk){if(code>packet.sender)release();else return}const starting=!!d.on&&!remoteTalking;remoteTalking=!!d.on;if(starting){if(!d.session)playAlert('direct');if(navigator.vibrate)navigator.vibrate([80,40,80]);if(document.hidden&&!pushActive)backgroundAlert(displayName()+' chamou no rádio')}$('radioState').textContent=remoteTalking?displayName()+' está falando…':talk?'Você está falando':'Canal livre'}if(d.type==='pcm'){pcmReceived++;await playPCM(d)}}

async function poll(){if(pollBusy||!online)return;pollBusy=true;let delay=document.hidden?800:350;try{const d=await api('poll',{query:{after:cursor}});for(const p of d.packets){await receive(p);cursor=Math.max(cursor,p.id)}if(d.packets.length)try{localStorage.setItem('pulso.cursor.v1',String(cursor))}catch{}retryDelay=1500;}catch(e){delay=2000;status('Reconectando ao servidor…');if(e.status===401){online=false;controls();scheduleReconnect()}}finally{pollBusy=false;clearTimeout(pollTimer);pollTimer=setTimeout(poll,delay)}}

async function heartbeat(){if(!online){scheduleReconnect();return}if(heartbeatBusy)return;heartbeatBusy=true;try{await api('heartbeat',{method:'POST',body:{enabled:radioEnabled,name:$('name').value||'Contato',foreground:!document.hidden}});if(!radioEnabled){status('Rádio desligado • sem recebimento');return}if(conn){const d=await api('contact',{query:{code:conn.code}});if(d.name&&d.name!=='Contato'){conn.name=d.name;renderContact()}status(d.online?'Conectado pelo servidor':d.reachable?'Contato em segundo plano • alertas ativos':'Contato salvo • aguardando ficar online')}else status('Rádio online • disponível');retryDelay=1500}catch{status('Sem conexão com o servidor. Reconectando…');scheduleReconnect()}finally{heartbeatBusy=false}}
function scheduleReconnect(){if(retryTimer||!radioEnabled||registering)return;retryTimer=setTimeout(()=>{retryTimer=null;register()},retryDelay);retryDelay=Math.min(30000,retryDelay*2)}

async function register(){if(registering)return;registering=true;try{$('retryRadio').hidden=true;status('Registrando rádio no servidor…');const d=await api('register',{method:'POST',body:{name:$('name').value||'Contato'}});if(!cursor)cursor=d.cursor;online=true;refreshAvatar(code,true);retryDelay=1500;$('code').textContent=pretty(code);$('headerId').textContent='ID '+pretty(code);$('savedHint').textContent='Código fixo salvo neste navegador.';status('Rádio online • conexão pelo servidor');controls();await restoreContact();poll();clearInterval(heartbeatTimer);heartbeatTimer=setInterval(heartbeat,10000);setupMediaPeer();await setupServiceWorker();await heartbeat()}catch(e){online=false;$('code').textContent=pretty(code);status(e.message);$('retryRadio').hidden=false;controls();if(e.status===409)toast(e.message);else{registering=false;scheduleReconnect()}}finally{registering=false}}

function init(){try{code=localStorage.getItem(CODE_KEY)||'';if(!/^[1-9]\d{5}$/.test(code)){const restore=new URLSearchParams(location.hash.slice(1)).get('radio');code=/^[1-9]\d{5}$/.test(restore||'')?restore:String(100000+crypto.getRandomValues(new Uint32Array(1))[0]%900000);localStorage.setItem(CODE_KEY,code)}secret=localStorage.getItem(TOKEN_KEY)||'';if(!/^[a-f0-9]{64}$/.test(secret)){secret=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');localStorage.setItem(TOKEN_KEY,secret)}$('name').value=localStorage.getItem('pulso.name')||'';const params=new URLSearchParams(location.hash.slice(1)),target=params.get('contato')||localStorage.getItem('pulso.contact.v1');if(/^[1-9]\d{5}$/.test(target||'')){$('target').value=pretty(target);$('contactSaved').textContent='Contato salvo: '+pretty(target)}$('headerId').textContent='ID '+pretty(code);register()}catch{status('Permita o armazenamento do navegador para usar seu código fixo.')}}
