$('connect').onclick=connectSavedContact;
$('directCall').onsubmit=async e=>{e.preventDefault();const to=normalize($('quickTarget').value);$('target').value=to;if(to!==conn?.code)$('contactAlias').value=readSavedContacts().find(c=>c.code===to)?.alias||'';await connectSavedContact()};

$('radioPower').onclick=async()=>{if(radioEnabled&&stream){radioEnabled=false;stopMic();endVideo();$('radioState').textContent='Rádio desligado';status('Rádio desligado • sem recebimento');controls();await heartbeat();wakeLock?.release().catch(()=>{});return}try{await prepareMic();radioEnabled=true;if(!online)await register();await heartbeat();controls();await keepAwake();toast('Rádio pronto para ouvir e falar.')}catch(e){toast(e.message)}};

