let held=false,holdEpoch=0,activePointer=null,holdKind='',holdTimer=null;
function beginHold(kind,pointer=null,mode='direct'){if(!held)$(mode==='talk'?'talkPtt':'ptt').classList.add('pressing');if(mode==='talk'&&talkSession?.state!=='accepted'){requestTalk().catch(e=>toast(e.message));return}if(held)return;holdMode=mode;held=true;holdKind=kind;activePointer=pointer;const epoch=++holdEpoch;clearTimeout(holdTimer);holdTimer=setTimeout(()=>{if(held&&holdEpoch===epoch){release();toast('Transmissão encerrada após 60 segundos. Solte e aperte novamente.')}},60000);press(epoch)}
function finishPointer(event){if(holdKind==='pointer'&&activePointer!==null&&event?.pointerId!==undefined&&event.pointerId!==activePointer)return;release()}
for(const [id,mode] of [['ptt','direct'],['talkPtt','talk']]){const b=$(id);b.addEventListener('pointerdown',e=>{if(e.isPrimary===false||(e.button!==undefined&&e.button!==0))return;e.preventDefault();beginHold('pointer',e.pointerId,mode);try{b.setPointerCapture(e.pointerId)}catch{}});for(const type of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,finishPointer);if(!('PointerEvent' in window)){b.addEventListener('touchstart',e=>{e.preventDefault();beginHold('touch',null,mode)},{passive:false});b.addEventListener('mousedown',e=>{if(e.button===0){e.preventDefault();beginHold('mouse',null,mode)}})}b.addEventListener('contextmenu',e=>{e.preventDefault()});b.addEventListener('dragstart',e=>{e.preventDefault();release()});b.addEventListener('blur',release);b.onkeydown=e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();beginHold('keyboard',null,mode)}};b.onkeyup=e=>{if([' ','Enter'].includes(e.key))release()};}
for(const type of ['pointerup','pointercancel'])window.addEventListener(type,finishPointer,true);window.addEventListener('touchend',()=>{if(holdKind!=='keyboard')release()},true);window.addEventListener('touchcancel',release,true);window.addEventListener('mouseup',()=>{if(holdKind==='mouse')release()},true);window.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)&&holdKind==='keyboard')release()},true);window.addEventListener('blur',release);window.addEventListener('pagehide',release);
let unread=0;function messagesPage(open){release();$('radioHome').hidden=open;$('messagesPage').hidden=!open;if(open){unread=0;$('messageBadge').textContent='';$('text').focus()}location.hash=open?'mensagens':'';} $('openMessages').onclick=()=>messagesPage(true);$('backRadio').onclick=()=>messagesPage(false);window.addEventListener('hashchange',()=>{const open=location.hash==='#mensagens';$('radioHome').hidden=open;$('messagesPage').hidden=!open});
