$('attach').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];$('file').value='';if(!f||!conn)return;if(f.size===0||f.size>20*1024*1024)return toast('Envie um arquivo entre 1 byte e 20 MB.');$('attach').disabled=true;const indicator=log('Enviando '+f.name+'…',false,true);try{const d=await api('upload',{method:'POST',query:{to:conn.code,name:f.name},body:f,raw:true});fileMessage(d,true);indicator.textContent='Arquivo enviado.'}catch(e){indicator.textContent=e.message}finally{controls()}};
$('retryRadio').onclick=register;$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(code);toast('Código copiado!')}catch{toast('Seu código é '+pretty(code))}};$('share').onclick=async()=>{const u=new URL(API_ORIGIN);u.hash='contato='+code;try{if(navigator.share)await navigator.share({title:'Pulso',text:'Salve meu rádio para falar comigo.',url:u.href});else{await navigator.clipboard.writeText(u.href);toast('Convite copiado!')}}catch{}};$('help').onclick=()=>{$('menu').close();$('info').showModal()};$('closeInfo').onclick=()=>$('info').close();
function setupMediaPeer(){if(typeof Peer==='undefined'||mediaPeer)return;mediaPeer=new Peer(PREFIX+code);mediaPeer.on('error',()=>{});mediaPeer.on('call',c=>{if(!conn||c.peer!==PREFIX+conn.code||videoCall||pendingCall){c.close();return}pendingCall=c;$('inviteTitle').textContent='Chamada recebida';$('inviteText').textContent='Chamada contínua '+(c.metadata?.video?'com vídeo':'de áudio')+' de '+conn.name;$('invite').showModal();playAlert('call')})}
function attachVideo(c,s,video){videoCall=c;release();$('local').srcObject=s;$('local').hidden=!video;$('remote').hidden=!video;$('camera').hidden=!video;$('videoPanel').classList.add('on');c.on('stream',r=>{$('remote').srcObject=r;$('remote').play().catch(()=>toast('Toque no vídeo para liberar o som.'))});c.on('close',()=>{if(videoCall===c)endVideo()});c.on('error',()=>{toast('A rede bloqueou a chamada direta. O rádio continua disponível pelo servidor.');endVideo()});setTimeout(()=>{if(videoCall===c&&!$('remote').srcObject){toast('A chamada direta não conectou. Use o rádio pelo servidor.');endVideo()}},30000)}
function endVideo(){const c=videoCall;videoCall=null;c?.close();const s=$('local').srcObject;s?.getTracks().forEach(t=>t.stop());$('local').srcObject=null;$('remote').srcObject=null;$('videoPanel').classList.remove('on')}
async function dialVideo(video){if(!conn||videoCall)return;try{const s=await navigator.mediaDevices.getUserMedia({audio:true,video});attachVideo(mediaPeer.call(PREFIX+conn.code,s,{metadata:{video}}),s,video)}catch{toast('Permita câmera e microfone para fazer a chamada.')}}$('audio').onclick=()=>dialVideo(false);$('video').onclick=()=>dialVideo(true);$('accept').onclick=async()=>{const c=pendingCall;pendingCall=null;$('invite').close();if(!c)return;try{const s=await navigator.mediaDevices.getUserMedia({audio:true,video:!!c.metadata?.video});attachVideo(c,s,!!c.metadata?.video);c.answer(s)}catch{c.close();toast('Permita o microfone para atender.')}};$('reject').onclick=()=>{pendingCall?.close();pendingCall=null;$('invite').close()};$('invite').addEventListener('cancel',e=>{e.preventDefault();$('reject').click()});$('end').onclick=endVideo;$('mute').onclick=()=>{const t=$('local').srcObject?.getAudioTracks()[0];if(t){t.enabled=!t.enabled;$('mute').textContent=t.enabled?'Silenciar':'Ativar microfone'}};$('camera').onclick=()=>{const t=$('local').srcObject?.getVideoTracks()[0];if(t)t.enabled=!t.enabled};$('remote').onclick=()=>$('remote').play();window.addEventListener('beforeunload',()=>{release();stopMic();endVideo();mediaPeer?.destroy()});

function radioBeep(kind='receive'){if(!beepOn||!context||context.state!=='running')return;if(!callTone){fallbackBeep(kind);loadCallTone().catch(()=>{});return}const node=context.createBufferSource(),gain=context.createGain(),at=context.currentTime;node.buffer=callTone;gain.gain.value=kind==='send'?.28:.65;node.connect(gain);gain.connect(context.destination);const duration=kind==='send'?Math.min(.22,callTone.duration):callTone.duration;node.start(at,0,duration);if(kind==='receive')nextAudio=Math.max(nextAudio,at+duration+.08)}
function fallbackBeep(kind='receive'){if(!beepOn||!context||context.state!=='running')return;const at=context.currentTime,notes=kind==='send'?[1040,1480]:[1480,1040];notes.forEach((hz,i)=>{const oscillator=context.createOscillator(),gain=context.createGain(),start=at+i*.095;oscillator.type='sine';oscillator.frequency.value=hz;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.13,start+.008);gain.gain.setValueAtTime(.13,start+.065);gain.gain.linearRampToValueAtTime(0,start+.08);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+.085)});if(kind==='receive')nextAudio=Math.max(nextAudio,at+.6)}
async function keepAwake(){if(document.hidden||!stream||!radioEnabled||!navigator.wakeLock||wakeLock)return;try{wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null})}catch{}}
async function backgroundAlert(title,type="direct"){if(!serviceWorker||!('Notification' in window)||Notification.permission!=='granted')return;try{await serviceWorker.showNotification(title,{body:'Toque para abrir seu rádio.',icon:'/icon-192.png',badge:'/icon-192.png',tag:'pulso-radio',...((type==='message'?soundSettings.message==='off':!beepOn||soundSettings.call==='off'||(type==='direct'&&!soundSettings.direct))?{silent:true}:{vibrate:[100,50,100]}),data:{url:'/'}})}catch{}}
function pushBytes(value){const raw=atob(value.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function setupServiceWorker(){if(window.Capacitor?.isNativePlatform?.()||!('serviceWorker' in navigator)){$('pushState').textContent='Neste aparelho, alertas nativos serão integrados na versão APK.';return}try{await navigator.serviceWorker.register('/sw.js',{scope:'/'});serviceWorker=await navigator.serviceWorker.ready;syncWorkerSounds();const subscription=await serviceWorker.pushManager?.getSubscription();pushActive=!!subscription&&Notification.permission==='granted';if(pushActive){await api('push-subscribe',{method:'POST',body:{endpoint:subscription.endpoint}});$('pushState').textContent='Alertas em segundo plano ativados.';$('disableAlerts').hidden=false;$('enableAlerts').textContent='Alertas ativados'}}catch{$('pushState').textContent='Alertas indisponíveis neste navegador. Use Chrome ou o app na tela inicial.'}}
$('checkAudio').onclick=async()=>{try{await sound();await playAlert('call',true)}catch{}toast('Versão 1.1.1 · Som: '+(context?.state||'não ativado')+' · Microfone: '+(stream?.getAudioTracks().some(t=>t.readyState==='live')?'liberado':'não liberado')+' · Voz enviada: '+pcmSent+' · Recebida: '+pcmReceived+' · Sinal: '+Math.round(micPeak*100)+'%')};$('openMenu').onclick=()=>$('menu').showModal();$('closeMenu').onclick=()=>$('menu').close();$('menu').addEventListener('click',e=>{if(e.target===$('menu')){const r=$('menu').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)$('menu').close()}});$('quickMic').onclick=async()=>{try{await prepareMic();await sound();radioEnabled=true;if(!online)await register();await heartbeat();controls();toast('Áudio liberado. Segure TALK ou o microfone para falar.')}catch(e){toast('Não foi possível ativar o áudio: '+e.message)}};$('beepEnabled').checked=beepOn;$('beepEnabled').onchange=()=>{beepOn=$('beepEnabled').checked;try{localStorage.setItem('pulso.beep',beepOn?'on':'off')}catch{}syncWorkerSounds();window.PulsoAndroid?.syncState().catch(()=>{})};$('testBeep').onclick=async()=>{try{await sound();await playAlert('call',true)}catch(e){toast(e.message)}};$('testMessageSound').onclick=async()=>{try{await sound();await playAlert('message',true)}catch(e){toast(e.message)}};for(const [id,value]of [['callSound',soundSettings.call],['messageSound',soundSettings.message],['hardwareButton',soundSettings.button],['hardwareMode',soundSettings.mode]]){$(id).value=value;$(id).onchange=saveSoundSettings}$('directToneEnabled').checked=soundSettings.direct;$('directToneEnabled').onchange=saveSoundSettings;
$('enableAlerts').onclick=async()=>{try{if(!('Notification' in window)||!('PushManager' in window)||!('serviceWorker' in navigator))return toast('Abra em Chrome no Android. No iPhone, adicione à Tela de Início e abra por lá.');const permission=await Notification.requestPermission();if(permission!=='granted')return toast('Permita as notificações nas configurações do navegador.');await setupServiceWorker();if(!serviceWorker)throw Error('Não foi possível preparar os alertas.');const key=await api('push-key');if(!key.publicKey)throw Error('O serviço de alertas ainda não foi configurado.');const subscription=await serviceWorker.pushManager.getSubscription()||await serviceWorker.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:pushBytes(key.publicKey)});syncWorkerSounds();await api('push-subscribe',{method:'POST',body:{endpoint:subscription.endpoint}});pushActive=true;$('pushState').textContent='Alertas em segundo plano ativados. O celular controla a entrega.';$('enableAlerts').textContent='Alertas ativados';$('disableAlerts').hidden=false;await heartbeat();toast('Alertas ativados. Toque no aviso para abrir o rádio.')}catch(e){toast(e.message||'Não foi possível ativar os alertas.')}};
$('disableAlerts').onclick=async()=>{try{await api('push-unsubscribe',{method:'POST',body:{}});const subscription=await serviceWorker?.pushManager.getSubscription();await subscription?.unsubscribe();pushActive=false;$('pushState').textContent='Alertas em segundo plano desativados.';$('disableAlerts').hidden=true;$('enableAlerts').textContent='Ativar alertas do celular'}catch(e){toast(e.message)}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('installApp').textContent='Instalar Pulso no celular'});$('installApp').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('No menu do navegador, escolha Instalar app ou Adicionar à Tela de Início.')};
if('serviceWorker' in navigator)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='open-radio'&&/^[1-9]\d{5}$/.test(e.data.code||'')){api('contact',{query:{code:e.data.code}}).then(d=>{link(e.data.code,d.name);$('target').value=pretty(e.data.code)}).catch(()=>{});toast('Toque em Ativar áudio para ouvir o rádio.')}});

window.PulsoHardwarePTT=(down)=>{if(!down){if(holdKind==='hardware')release();else if(!held)for(const id of ['ptt','talkPtt'])$(id).classList.remove('pressing');return}if(document.hidden||$('menu').open||$('talkInvite').open||$('invite').open||$('info').open||$('contactsDialog').open||!online||!radioEnabled||!conn||!$('messagesPage').hidden)return;beginHold('hardware',null,soundSettings.mode)};
let fullscreenOn=true;try{fullscreenOn=localStorage.getItem('pulso.fullscreen.v1')!=='off'}catch{}$('fullscreenEnabled').checked=fullscreenOn;$('fullscreenEnabled').disabled=!window.PulsoAndroid;if(!window.PulsoAndroid)$('fullscreenHint').textContent='Tela cheia automática disponível no APK. No navegador, instale na tela inicial.';$('fullscreenEnabled').onchange=async()=>{const next=$('fullscreenEnabled').checked;try{await window.PulsoAndroid?.fullscreen(next);localStorage.setItem('pulso.fullscreen.v1',next?'on':'off');fullscreenOn=next}catch{ $('fullscreenEnabled').checked=fullscreenOn;toast('Não foi possível alterar a tela cheia.')}};
